const items = $input.all();
if (!items || !items.length) return [];

const trad = {
  'Open': 'Abierto', 'In Progress': 'En Progreso',
  'Wait': 'Esperando', 'Coordinated': 'Coordinado', 'Pending': 'Pendiente'
};
const LIMITE = 8;
const agrupar  = {};
const yaVistos = new Set();

for (const item of items) {
  const d        = item.json;
  const tel      = d.Numero_Whatsapp;
  const tecnico  = d.tecnico_asignado;
  const ticketId = d.ticketid;
  if (!tel || !tecnico || !ticketId) continue;

  const key = `${tel}_${ticketId}`;
  if (yaVistos.has(key)) continue;
  yaVistos.add(key);

  if (!agrupar[tel]) agrupar[tel] = { tecnico, tickets: [], total: 0 };
  agrupar[tel].total++;
  if (agrupar[tel].tickets.length >= LIMITE) continue;

  const estado = trad[d.status] || d.status || 'N/A';
  const link   = `https://your-crm.example.com/index.php?module=HelpDesk&view=Detail&record=${ticketId}&app=SUPPORT`;

  agrupar[tel].tickets.push(
    `*${d.ticket_no}* — ${d.empresa || 'N/A'} | ${estado}\n` +
    `\u{1F517} ${link}`
  );
}

const resultados = [];
for (const [tel, d] of Object.entries(agrupar)) {
  if (!d.tickets.length) continue;

  const tzOpts = { timeZone: 'America/Argentina/Buenos_Aires' };
  const ahora  = new Date();
  const hora   = ahora.toLocaleTimeString('es-AR', Object.assign({hour:'2-digit', minute:'2-digit'}, tzOpts));
  const fecha  = ahora.toLocaleDateString('es-AR', Object.assign({day:'2-digit', month:'2-digit'}, tzOpts));
  const cant   = d.total;

  let msg = `\u{1F4CB} *Tickets Activos \u00B7 ${d.tecnico}*\n`;
  msg += `${fecha} \u00B7 ${hora}hs \u00B7 ${cant} ticket${cant > 1 ? 's' : ''}\n`;
  msg += `\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n`;
  msg += d.tickets.join('\n\n');
  if (cant > LIMITE) msg += `\n\n_...y ${cant - LIMITE} m\u00e1s en CRM_`;
  msg += `\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n`;
  msg += `_Actualiz\u00e1 el estado o avanz\u00e1 con la resoluci\u00f3n_`;

  resultados.push({ json: { numero_destino: tel, mensaje_texto: msg } });
}
return resultados;
